/* Borrowed Eyes — buildless, browser-local front-end prototype. No credentials or messages leave this device. */
'use strict';
const KEY='borrowedEyes.frontend.v3';
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')||{}}catch{return{}}};
const saved=read();
const S={user:saved.user||null,location:'unknown',locationMode:null,area:1,game:saved.game||null,history:saved.history||[],published:saved.published||[],messages:saved.messages||[],blocked:saved.blocked||[],friends:saved.friends||[],draft:saved.draft||null,lastCheckin:saved.lastCheckin||null};
let route='welcome',selectedId=null,filter='All',difficultyFilter=0,detailPage=0,teamTab='join',teamSize=3,teamNames=['You','Maya','Leo'],actor=0,role='guesser',blindTag=null,creatorStep=1,creatorClue=0,selectedVisitor=null,chatTarget='public',mapArea=null,locationIntent='home',locationWatch=null;
const view=document.querySelector('#view');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFKD').toLowerCase().replace(/[^a-z0-9]/g,'');
const works=()=>{const map=new Map(window.ARTWORKS.map(w=>[w.id,w]));for(const c of S.published){const id=c.artworkId||c.id;if(!map.has(id))map.set(id,{...c,id});}return [...map.values()]};
const all=()=>[...window.CHALLENGES.map(c=>({...window.ARTWORKS.find(w=>w.id===c.artworkId),...c})),...S.published];
const find=id=>all().find(a=>a.id===id)||works().find(a=>a.id===id);
const art=()=>find(S.game?.challengeId||selectedId)||all()[0];
const stars=n=>`<span class="stars" aria-label="${n} stars">${'★'.repeat(n)}</span>`;
const areas=['Upper left','Upper right','Lower left','Lower right'];
const icons={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',map:'M12 22S4 15 4 9a8 8 0 0 1 16 0c0 6-8 13-8 13Z M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',chat:'M20 16a9 9 0 0 1-10 3l-6 3 1-6A9 9 0 1 1 20 16Z',profile:'M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3Z',back:'m15 5-7 7 7 7M8 12h13',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.eye}"/></svg>`;
const btn=(label,action,value='',cls='')=>`<button type="button" class="button ${cls}" data-do="${action}" data-value="${esc(value)}">${label}</button>`;
const back=(target='home',label='Back')=>`<button class="back" data-go="${target}">${icon('back')}${label}</button>`;
const title=(kicker,name,copy='')=>`<div class="page-title"><p class="eyebrow">${kicker}</p><h1>${name}</h1>${copy?`<p>${copy}</p>`:''}</div>`;
const field=(label,name,type='text',placeholder='',value='',extra='')=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${extra}></label>`;
const avatar=(i=0,name='Visitor')=>`<img class="avatar" src="assets/ui/visitor-${['amara','maya','theo','lina'][i%4]}.jpg" alt="${esc(name)}">`;
const fullImage=(a,cls='art-hero')=>`<figure class="${cls}" style="margin:0"><img src="${esc(a.image)}" alt="${esc(a.title)}" loading="lazy" data-art-image><figcaption class="small" hidden>Artwork image unavailable. Reopen the complete project or the single-file preview.</figcaption></figure>`;
let clipSequence=0;
function fragment(a){if(a.fragment)return `<div class="art-hero"><img src="${esc(a.fragment)}" alt="Mystery detail"></div>`;const c=a.crop;if(!c)return '<p class="empty">Choose a detail challenge to start.</p>';const b=a.imageBounds||{x:0,y:0,w:1,h:1},iw=a.imageWidth||1200,ih=a.imageHeight||900;const x=(b.x+c.x*b.w)*iw,y=(b.y+c.y*b.h)*ih,w=c.w*b.w*iw,h=c.h*b.h*ih;const image=window.ART_ASSETS?.[a.image]||a.image,clip='detail-clip-'+(++clipSequence),displayScale=Math.min(1/1.5,480/w,420/h),displayWidth=Math.floor(w*displayScale);return `<div class="fragment-stage"><div class="fragment-art" style="--detail-width:${displayWidth}px;--detail-ratio:${w/h};aspect-ratio:${w}/${h}"><svg viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="A cropped mystery artwork detail" preserveAspectRatio="xMidYMid meet"><defs><clipPath id="${clip}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><image href="${esc(image)}" width="${iw}" height="${ih}" clip-path="url(#${clip})" preserveAspectRatio="none"/></svg></div></div>`;}
const suffixClues=a=>a.clues.slice(5-a.stars).map((text,i)=>({q:6-a.stars+i,text}));
function persist(){try{localStorage.setItem(KEY,JSON.stringify({user:S.user,game:S.game,history:S.history,published:S.published,messages:S.messages,blocked:S.blocked,friends:S.friends,draft:S.draft,lastCheckin:S.lastCheckin}));return true}catch{toast('Browser storage is full. Keep this page open, or use smaller uploaded images.');return false}}
let toastTimer;function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200)}
function notice(name,copy){document.querySelector('#notice-title').textContent=name;document.querySelector('#notice-copy').textContent=copy;document.querySelector('#notice').showModal()}
function active(){return S.game&&!S.game.finished}
function limit(g=S.game,a=art()){return g.mode==='blind'?a.stars+1:a.stars+1-g.players.length}
function left(){return Math.max(0,limit()-S.game.attempts)}
function gameRoute(){return S.game?.mode==='blind'?'blind-chat':'play'}
function go(next){route=next;if(!S.user&&!['welcome','login','signup','reset','reset-sent','terms'].includes(route))route='welcome';render();window.scrollTo({top:0,behavior:'auto'});view.focus({preventScroll:true});}
function shell(){const showNav=!['welcome','login','signup','reset','reset-sent','terms'].includes(route);document.querySelector('#masthead').innerHTML=`<button class="wordmark" data-go="${S.user?'home':'welcome'}">Borrowed Eyes<small>Museum</small></button><div class="header-right"><span class="header-note">ART · PEOPLE · PLACES<br>NEW PERSPECTIVES</span><button class="demo-label" data-do="about">Local prototype</button>${S.user?`<span class="stars">★ ${S.history.reduce((n,g)=>n+g.reward,0)}</span><button class="round-icon" aria-label="Your profile" data-go="profile">${esc(S.user.name[0].toUpperCase())}</button>`:''}<button class="round-icon" aria-label="Open menu" data-go="menu">${icon('menu')}</button></div>`;const nav=document.querySelector('#navigation');nav.hidden=!showNav;const tab=['map','area','catalogue'].includes(route)?'map':['chat','visitor','conversation','chat-team'].includes(route)?'chat':route==='profile'?'profile':'home';nav.innerHTML=['home','map','chat','profile'].map(n=>`<button data-go="${n}" class="${tab===n?'active':''}" ${tab===n?'aria-current="page"':''}>${icon(n)}<span>${n[0].toUpperCase()+n.slice(1)}</span></button>`).join('');}
const footer=()=>`<footer class="footer-note">Different perspectives. A richer world.<small>Art · People · Places · Borrowed Eyes Museum</small></footer>`;
function render(){shell();const pages={welcome,login:()=>auth(false),signup:()=>auth(true),reset, 'reset-sent':resetSent,terms,home,menu,browse,detail,teams,lobby,comment,play,clues,'game-chat':gameChat,guess,wrong,result,'blind-role':blindRole,'blind-tags':blindTags,'blind-match':blindMatch,'blind-summary':blindSummary,'blind-chat':blindChat,location:locationPage,'location-state':locationState,chat,visitor,conversation,'chat-team':chatTeam,map,area,catalogue,creator,'creator-preview':creatorPreview,'creator-success':creatorSuccess,profile,sources};if(['play','comment','clues','game-chat','guess','wrong','result','blind-chat'].includes(route)&&!S.game){route='home';}view.innerHTML=(pages[route]||home)();document.querySelectorAll('img[src^="assets/"]').forEach(img=>{const key=img.getAttribute('src'),uri=window.UI_ASSETS?.[key]||window.ART_ASSETS?.[key];if(uri)img.src=uri});document.title=`${({'blind-chat':'Blind Eyes',map:'Gallery Map',creator:'Leave Your Eyes',browse:'Borrow the Eyes'})[route]||'Borrowed Eyes'} · Museum`;if(route==='creator'&&creatorStep===3)bindCrop();document.querySelectorAll('.chat-log').forEach(el=>el.scrollTop=el.scrollHeight)}
function welcome(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">A museum of perspectives</p><h1>See art<br>through<br><em>new eyes.</em></h1><p>Some details stay with us. Borrow another visitor’s perspective and discover what you might have missed.</p><div class="hero-actions">${btn('Log In','navigate','login','light')}${btn('Create an Account','navigate','signup','secondary')}</div><button class="text-button" style="color:#eee0c8;margin-top:14px" data-do="guest">Explore the prototype →</button></div><span class="hero-foot">SAME ARTWORKS. DIFFERENT EYES.</span></section><div class="welcome-footer"><h3>A small detail.<br>A new way to see.</h3><p class="lede">Find a work through someone else’s memory, share a conversation, or leave a perspective of your own.</p></div>${footer()}`}
function auth(signup){return `${back('welcome')}<section class="auth"><img class="auth-image" src="assets/ui/museum-hero.jpg" alt="An illustrated museum gallery"><div class="auth-form"><p class="eyebrow">The visitor’s entrance</p><h1>${signup?'Create Your Account':'Welcome back.'}</h1><p class="small">${signup?'Join a community that sees art from new perspectives.':'Continue your museum journey.'}</p><form data-form="auth" data-signup="${signup}">${signup?field('Display name','name','text','How shall we call you?','', 'required maxlength="30"'):''}${field('Email address','email','email','you@example.com','','required autocomplete="email"')}<label class="field"><span>Password</span><div class="row" style="flex-wrap:nowrap"><input name="password" type="password" required minlength="8" autocomplete="${signup?'new-password':'current-password'}"><button class="text-button" type="button" data-do="show-password">Show</button></div></label>${signup?field('Confirm password','confirm','password','','','required minlength="8"'):`<div class="row spread small" style="margin-bottom:20px"><label><input type="checkbox" name="remember"> Remember me</label><button type="button" class="text-button" data-go="reset">Forgot password?</button></div>`}${signup?`<label class="small" style="display:block;margin-bottom:20px"><input type="checkbox" required> I agree to the <button type="button" class="text-button" data-do="terms">prototype terms and privacy notice</button>.</label>`:''}<p class="form-error" role="alert"></p><button class="button full">${signup?'Create Account':'Log In'}</button></form><p class="small center" style="margin-top:20px">${signup?'Already have an account?':'Don’t have an account?'} <button class="text-button" data-go="${signup?'login':'signup'}">${signup?'Log In':'Sign Up'}</button></p><p class="rule">Front-end demonstration. This form validates locally; it does not create an online account or store your password. Use sample details.</p>${btn('Continue as a visitor','guest','','secondary full')}</div></section>`}
function reset(){return `${back('login')}<div class="narrow panel">${title('Account access','Reset Password','Enter an email to preview the password-reset flow.')}<form data-form="reset">${field('Email address','email','email','you@example.com','','required')}<button class="button full">Preview Reset Request</button></form><p class="rule">No email is sent in this front-end prototype.</p></div>`}
function resetSent(){return `<div class="narrow panel sage center"><div class="result-seal">✓</div><h2>Reset request previewed.</h2><p>In the connected version, an eligible account would receive a password-reset email. This demo has not sent an email.</p>${btn('Back to Log In','navigate','login','secondary')}</div>`}
function terms(){return `${back('welcome')}<div class="narrow panel"><h2>Prototype privacy</h2><p>This is an educational front-end demonstration. Sample profiles, partners and conversations are fictional. Comments, drafts and game progress save in this browser when storage is available.</p><p>Passwords are never saved. Location is requested only after you choose it; no coordinates are stored or shared. Museum images load from the credited museum service.</p></div>`}
function home(){const entries=[['Borrow the Eyes','Find a work through another visitor’s perspective.','borrow-illustration','browse','Begin exploring'],['Blind Eyes','Two perspectives. One shared discovery.','blind-illustration','blind-role','Find a partner'],['Live Gallery Chat','Meet fellow visitors and explore together.','chat-illustration','chat','Join the room'],['Leave Your Eyes','Turn a detail into a new perspective.','leave-illustration','creator','Create a task']];return `<section class="hero home-hero"><div class="hero-copy"><p class="eyebrow">Welcome back, ${esc(S.user.name)}</p><h1>Look a little<br><em>closer.</em></h1><p>There is more than one way to see a work of art.</p></div><span class="hero-foot">YOUR NEXT PERSPECTIVE IS WAITING</span></section>${active()?`<div class="panel sage row spread"><div><strong>Your discovery is still waiting.</strong><p class="small" style="margin:0">${S.game.mode==='blind'?'Blind Eyes':'Borrow the Eyes'} · ${left()} attempts remaining</p></div>${btn('Continue challenge','navigate',gameRoute())}</div>`:''}<div class="section-head"><h2>Choose your curiosity</h2><small>Four ways to see</small></div><div class="entry-grid">${entries.map(([name,copy,img,to,link])=>`<button class="entry" data-go="${to}"><img src="assets/ui/${img}.jpg" alt=""><span class="entry-body"><h3>${name}</h3><p>${copy}</p><span class="entry-arrow">${link}<b>→</b></span></span></button>`).join('')}</div>${footer()}`}
function menu(){return `${back()}<div class="narrow panel"><p class="eyebrow">Your museum companion</p><h2>Where would you like to go?</h2><div class="stack">${[['Home','home'],['Borrow the Eyes','browse'],['Blind Eyes','blind-role'],['Live Gallery Chat','chat'],['Leave Your Eyes','creator'],['Gallery Map','map'],['Location & access','location'],['Your notebook','profile'],['Artwork credits','sources']].map(([n,to])=>btn(n,'navigate',to,'secondary')).join('')}${btn('Log out of prototype','logout','','secondary')}</div></div>`}
function browse(){const details=all().filter(a=>(filter==='All'||a.category===filter)&&(!difficultyFilter||a.stars===difficultyFilter)).sort((a,b)=>b.stars-a.stars||(a.variant||0)-(b.variant||0)||(a.workIndex||0)-(b.workIndex||0));const pages=Math.max(1,Math.ceil(details.length/12));detailPage=Math.min(detailPage,pages-1);const visible=details.slice(detailPage*12,detailPage*12+12);return `${back()}${title('Borrow the Eyes','A detail that makes you look again.','Tiny objects. Unnoticed corners. A whole new way into the painting.')}<div class="collection-summary"><span><strong>${works().length}</strong> original artworks</span><span><strong>${all().length}</strong> different details</span><button class="text-button" data-do="difficulty-help">How difficulty works</button></div><div class="chips">${['All','Objects','Architecture','Nature','Landscape','People','History'].map(c=>`<button class="chip ${filter===c?'active':''}" data-do="filter" data-value="${c}">${c}</button>`).join('')}</div><div class="difficulty-filters" aria-label="Filter by difficulty"><button class="chip ${!difficultyFilter?'active':''}" data-do="difficulty-filter" data-value="0">All levels</button>${[5,4,3,2,1].map(n=>`<button class="chip ${difficultyFilter===n?'active':''}" data-do="difficulty-filter" data-value="${n}">${'★'.repeat(n)}<span class="visually-hidden"> ${n} stars</span></button>`).join('')}</div><p class="small">${details.length} details · ${difficultyFilter?'Selected difficulty':'Hardest first'} · Every card is a separate crop and challenge.</p><div class="art-grid">${visible.map(a=>`<button class="art-card" data-do="select-art" data-value="${a.id}">${fragment(a)}<p class="caption">A visitor’s perspective</p><h3>${esc(a.comment)}</h3>${stars(a.stars)}<p>${(a.ratio*100).toFixed(2)}% of the original · ${esc(a.category)}</p></button>`).join('')||'<div class="empty">No details match both filters. Try another category or star level.</div>'}</div><div class="pagination">${btn('← Previous','detail-page',Math.max(0,detailPage-1),'secondary')}<span>Page ${detailPage+1} of ${pages}</span>${btn('Next →','detail-page',Math.min(pages-1,detailPage+1),'secondary')}</div>`}
function detail(){const a=find(selectedId)||all()[0];return `${back('browse','Back to fragments')}<div class="layout"><div>${fragment(a)}<p class="caption">A borrowed detail · identity hidden</p><p class="small">Crop area: ${(a.ratio*100).toFixed(2)}% of the original artwork.</p></div><div><p class="eyebrow">Borrow the Eyes</p><h1 style="font-size:43px">${esc(a.comment)}</h1>${stars(a.stars)}<p class="caption">Creator’s personal comment</p><blockquote class="quote">${esc(a.reflection)}</blockquote><p class="small" style="margin-top:12px">Original fictional visitor reflection · demo content</p><div class="stats"><div><strong>${a.stars}</strong><small>Difficulty</small></div><div><strong>${a.stars}</strong><small>Total clues</small></div><div><strong>${a.stars}</strong><small>Solo attempts</small></div></div><div class="row">${btn('Play Alone','begin-solo',a.id)}${btn('Play Together','team-choice',a.id,'secondary')}</div><p class="rule">Borrow attempts = difficulty + 1 − players.<br>Each player posts one personal comment to unlock one clue.</p></div></div>`}
function gate(){return `<div class="gallery-gate">${icon('map')}<div><strong>${S.location==='inside'?'Gallery verified · classroom demo':'Gallery access required'}</strong><br><span>${S.location==='inside'?'You can join an on-site team.':'Verify gallery access to play together.'}</span></div></div>`}
function teams(){const a=find(selectedId)||all()[0];if(S.location!=='inside'){locationIntent='teams';return `${back('detail')}<div class="narrow panel">${title('Play together','Find your circle.','On-site teams require gallery verification.')}${gate()}${btn('Verify Gallery Access','navigate','location','full')}${btn('Play Alone Instead','begin-solo',a.id,'secondary full')}</div>`}return `${back('detail')}<div class="narrow">${title('Borrow the Eyes','Find or create a team.','One discovery, shared through different eyes.')}${gate()}<div class="tabs"><button class="${teamTab==='join'?'active':''}" data-do="team-tab" data-value="join">Join a Team</button><button class="${teamTab==='create'?'active':''}" data-do="team-tab" data-value="create">Create a Team</button></div>${teamTab==='join'?`<div class="panel">${['Art Explorers','Canvas Friends','Museum Wanderers'].map((name,i)=>`<div class="list-row">${avatar(i,name)}<div class="grow"><h4>${name}</h4><p>${Math.min(i+1,a.stars-1)} / ${a.stars} members · sample team</p></div>${btn('Join','join-team',i,'secondary')}</div>`).join('')}</div>`:`<form class="panel" data-form="team-create">${field('Team name','name','text','Art Explorers','Art Explorers','required maxlength="40"')}<label class="field"><span>Players (including you)</span><select name="size">${Array.from({length:Math.max(0,a.stars-1)},(_,i)=>`<option value="${i+2}">${i+2} people</option>`).join('')}</select></label>${a.stars<2?'<p>A one-star task is solo only. Choose a harder task for a team.</p>':'<button class="button full">Create Team</button>'}</form>`}<p class="small">Matching and team members are simulated on this device.</p></div>`}
function lobby(){const a=find(selectedId)||art();return `${back('teams')}<div class="layout"><div>${fragment(a)}<p class="caption">${esc(a.comment)}</p></div><div class="panel"><p class="eyebrow">Team lobby</p><h2>${esc(S.teamName||'Art Explorers')}</h2><div class="member-list">${teamNames.slice(0,teamSize).map((n,i)=>`<div class="member">${avatar(i,n)}<span>${esc(n)}</span>${i===0?'<br><small>Host</small>':''}</div>`).join('')}</div><div class="status-line"><span>Difficulty</span><strong>${stars(a.stars)}</strong></div><div class="status-line"><span>Players</span><strong>${teamSize} / ${a.stars}</strong></div><div class="status-line"><span>Shared attempts</span><strong>${a.stars+1-teamSize} = ${a.stars} + 1 − ${teamSize}</strong></div><p class="small" style="margin-top:15px">The roster locks when the challenge begins. Each person must comment to unlock their own clue.</p>${btn('Start Challenge','begin-team',a.id,'full')}</div></div>`}
function startGame(mode,a,players,gameRole='guesser'){S.game={id:Date.now().toString(36),artId:a.artworkId||a.id,challengeId:a.id,mode,players,role:gameRole,attempts:0,comments:{},shared:[],messages:[],finished:false,cluesUnlocked:0};if(mode==='blind')S.game.messages=[{name:'Partner',text:'Hi! Take your time. Let’s look closely together.',mine:false}];actor=0;persist();go(mode==='blind'?'blind-chat':'comment')}
function comment(){const g=S.game,a=art();if(g.mode==='blind')return blindChat();const who=g.players[actor];return `${back('play','Back to challenge')}<div class="narrow">${title('Borrow the Eyes','Your personal comment.','What does this detail make you think of? A memory, feeling or small observation is enough.')}${fragment(a)}<form class="panel" data-form="comment" style="margin-top:20px"><p class="eyebrow">${esc(who)} · one comment, one clue</p><label class="field"><span>Your perspective</span><textarea name="comment" required maxlength="200" rows="4" placeholder="It reminds me of…" ${g.comments[actor]?'disabled':''}>${esc(g.comments[actor]||'')}</textarea></label><p class="small">${g.comments[actor]?'You have already unlocked your clue. Repeated comments cannot unlock another.':'Your clue is private until you share it with the team.'}</p>${g.comments[actor]?btn('View Your Clue','navigate','clues','full'):'<button class="button full">Submit Comment & Unlock Clue</button>'}</form></div>`}
function play(){const a=art(),g=S.game;return `${back()}<div class="layout"><div>${fragment(a)}<p class="caption">Creator’s comment</p><blockquote class="quote">${esc(a.reflection)}</blockquote></div><div><p class="eyebrow">Borrow the Eyes · ${g.players.length>1?'Team':'Solo'}</p><h2>${esc(a.comment)}</h2>${stars(a.stars)}<div class="stats"><div><strong>${g.players.length}</strong><small>Players</small></div><div><strong>${left()}</strong><small>Attempts left</small></div><div><strong>${Object.keys(g.comments).length}</strong><small>Clues unlocked</small></div></div>${g.players.length>1?`<label class="field"><span>Local team demonstration · viewing as</span><select id="actor-select">${g.players.map((n,i)=>`<option value="${i}" ${actor===i?'selected':''}>${esc(n)}${i?' (simulated)':''}</option>`).join('')}</select></label>`:''}<div class="stack">${btn(g.comments[actor]?'View Your Clue':'Write Your Comment','navigate',g.comments[actor]?'clues':'comment','secondary')}${g.players.length>1?btn('Team Chat · Share Clues','navigate','game-chat','secondary'):''}${btn('Open Gallery Map','navigate','map','secondary')}${btn('Submit an Answer','navigate','guess')}</div><p class="rule">${a.stars} + 1 − ${g.players.length} = ${limit()} formal attempts. No extra clues are provided after wrong Borrow answers.</p></div></div>`}
function clueMarkup(c,open,privateClue=false,areaHint=art().area){return `<article class="clue ${open?'':'locked'} ${privateClue?'private':''}"><span class="clue-number">Q${c.q}</span><div><h4>${['Abstract','Story','Visual','Relation','Gallery area'][c.q-1]} · ${open?'Unlocked':privateClue?'Private':'Locked'}</h4><p>${open?esc(c.text):privateClue?'Another visitor’s clue. Ask them to share it in team chat.':'This clue is not unlocked yet.'}</p>${open&&c.q===5?`<div style="max-width:300px;margin-top:12px">${zoneMap(areaHint,'hint')}</div>`:''}</div></article>`}
function clues(){const a=art(),g=S.game,cs=suffixClues(a);return `${back(gameRoute(),'Back to challenge')}<div class="narrow">${title('Shared looking','Your clue cabinet.','Clues follow a path from abstract to concrete.')}<p class="small">Viewing as ${esc(g.players[actor]||'You')}. Other players’ clues remain private until shared.</p>${cs.map((c,i)=>{const own=g.mode==='blind'?i<g.cluesUnlocked:Boolean(g.comments[i])&&(i===actor||g.shared.includes(i));return clueMarkup(c,own,g.mode!=='blind'&&Boolean(g.comments[i])&&!own)}).join('')}${g.mode!=='blind'&&g.comments[actor]&&g.players.length>1?btn(g.shared.includes(actor)?'Clue Shared':'Share Your Clue to Team','share-clue',actor,'full'):''}${g.mode!=='blind'&&!g.comments[actor]?btn('Write Your Comment','navigate','comment','full'):''}${btn('Open Gallery Map','navigate','map','secondary full')}</div>`}
function chatMessages(messages){return `<div class="chat-log" role="log" aria-label="Conversation">${messages.map((m,i)=>`<div class="message ${m.mine?'self':''}">${avatar(m.mine?0:i%4,m.name)}<div class="bubble"><small>${esc(m.name)} · ${esc(m.time||'Now')}</small>${esc(m.text)}</div></div>`).join('')||'<p class="small center">Begin with a hello. A shared discovery starts with a conversation.</p>'}</div>`}
const composer=(form='game-message',disabled=false)=>`<form class="composer" data-form="${form}"><label class="visually-hidden" for="message">Message</label><input id="message" name="message" required maxlength="500" placeholder="Share what you notice…" ${disabled?'disabled':''}><button class="button" ${disabled?'disabled':''} aria-label="Send message">↑</button></form>`;
function gameChat(){const a=art(),g=S.game;return `${back('play')}<div class="layout"><div><p class="eyebrow">Borrow the Eyes · Team conversation</p><h2>${esc(S.teamName||'Art Explorers')}</h2><p class="small">${g.players.length} players · ${left()} shared attempts</p>${chatMessages(g.messages)}${composer()}</div><aside class="panel"><h3>Your borrowed view</h3>${fragment(a)}<p class="caption">${esc(a.comment)}</p><div class="stack">${btn('Clue Cabinet','navigate','clues','secondary')}${btn('Open Map','navigate','map','secondary')}${btn('Submit an Answer','navigate','guess')}</div><p class="rule">This conversation is a local team demonstration. Switch players on the challenge page to contribute each simulated player’s comment.</p></aside></div>`}
function guess(){const g=S.game,a=art();if(g.finished)return result();if(g.mode==='blind'&&g.role==='describer')return blindChat();return `${back(gameRoute())}<div class="narrow panel">${title(g.mode==='blind'?'Blind Eyes':'Borrow the Eyes','Make a formal guess.','Enter the artwork title or its BE identifier from the exhibition label.')}<div class="stats"><div><strong>${left()}</strong><small>Attempts left</small></div><div><strong>${g.attempts}</strong><small>Used</small></div><div><strong>${limit()}</strong><small>Total</small></div></div><form data-form="guess">${field('Artwork title or ID','answer','text','e.g. BE-001','','required autocomplete="off"')}<p class="form-error" role="alert"></p>${g.players.length>1&&g.mode!=='blind'?'<label class="small" style="display:block;margin-bottom:18px"><input type="checkbox" name="agreement" required> We have discussed this answer and the team agrees to submit it.</label>':''}<button class="button full">${left()===1?'Submit Final Answer':'Submit Guess'}</button></form><p class="rule">Only a formal submission uses an attempt. Discussion and opening the map are free.</p></div>`}
function submitGuess(answer){const g=S.game,a=art();if(!g||g.finished||g.attempts>=limit()||(g.mode==='blind'&&g.role!=='guesser'))return false;g.attempts++;const success=[a.artworkId||a.id,a.title,a.titleZh,...(a.aliases||[])].some(x=>norm(x)===norm(answer));g.lastAnswer=answer;if(success||g.attempts>=limit()){g.finished=true;g.success=success;const before=S.history.some(h=>h.challengeId===a.id&&h.reward>0);S.history.push({id:g.id,artId:a.artworkId||a.id,challengeId:a.id,detailTitle:a.comment,mode:g.mode,success,attempts:g.attempts,reward:success&&!before?a.stars:0,date:new Date().toISOString()});}else if(g.mode==='blind')g.cluesUnlocked=Math.min(a.stars,g.attempts);persist();go(g.finished?'result':'wrong');return success}
function wrong(){const g=S.game,a=art(),c=suffixClues(a)[g.cluesUnlocked-1];return `${back(gameRoute())}<div class="narrow"><div class="panel rose center"><div class="result-seal fail">×</div><h2>Not quite right.</h2><p>${left()} formal ${left()===1?'attempt':'attempts'} remaining.</p><p class="small">Your guess: ${esc(g.lastAnswer)}</p></div>${g.mode==='blind'&&c?clueMarkup(c,true):'<div class="panel"><p>No additional clue is unlocked after a Borrow guess. Look again and discuss what you have noticed.</p></div>'}<div class="stack">${btn(g.mode==='blind'?'Continue Chat':'Try Again','navigate',g.mode==='blind'?'blind-chat':'guess')}${btn('Open Gallery Map','navigate','map','secondary')}</div></div>`}
function result(){const a=art(),g=S.game;if(!g?.finished)return play();return `<div class="layout"><div>${fullImage(a)}<p class="caption">${esc(a.artist)} · ${esc(a.date)} · ${esc(a.titleZh)}</p></div><div><div class="result-seal ${g.success?'':'fail'}" style="margin-left:0">${g.success?'✓':'×'}</div><p class="eyebrow">${g.success?'A shared discovery':'The artwork revealed'}</p><h1 style="font-size:43px">${g.success?'You found it.':'A new way to look next time.'}</h1><h3>${esc(a.title)}</h3><p class="small">${esc(a.artist)} · ${esc(a.date)}<br>${esc(a.medium)}</p><p>${esc(a.description)}</p><div class="panel ${g.success?'sage':'rose'}"><strong>${g.success?`${a.stars} stars for each participant.`:'No attempts left. No reward this round.'}</strong><p class="small" style="margin:6px 0 0">${g.success?'Full reward per person, never divided. Your notebook counts each different detail once; replaying the same detail does not add another reward.':'You can keep the conversation going or explore another perspective.'}</p></div><div class="stack">${g.mode==='blind'?btn('Continue Chat','navigate','blind-chat','secondary'):''}${btn('Try Another Perspective','navigate',g.mode==='blind'?'blind-tags':'browse')}${btn('Back to Map','navigate','map','secondary')}</div></div></div>`}
function blindRole(){return `${back()}${title('Blind Eyes','Two perspectives.<br>One shared discovery.','One visitor sees the artwork. The other discovers it through words.')}<div class="layout"><div><img class="location-art" style="height:390px" src="assets/ui/blind-illustration.jpg" alt="An illustrated gallery study"></div><div class="stack"><div class="panel"><p class="eyebrow">I · The describer</p><h3>Help someone see.</h3><p>You see the complete artwork, without its title or location. Describe it in your own words.</p>${btn('Be the Describer','choose-role','describer','full')}</div><div class="panel"><p class="eyebrow">II · The guesser</p><h3>Discover through words.</h3><p>You do not see the artwork. Ask questions, find clues and make the formal guesses.</p>${btn('Be the Guesser','choose-role','guesser','secondary full')}</div></div></div>`}
function blindTags(){return `${back('blind-role')}<div class="narrow">${title('Blind Eyes · Find a partner','What resonates with you?','Choose a creator’s personal comment. In this prototype, a sample partner chooses the same tag.')}<div class="stack">${all().map(a=>`<button class="button secondary" data-do="blind-tag" data-value="${a.id}" style="justify-content:space-between;text-align:left">${esc(a.comment)}<span>→</span></button>`).join('')}</div><p class="rule">Tags come from personal comments, not from formal clues. Partner matching is simulated locally.</p></div>`}
function blindMatch(){return `${back('blind-tags')}<div class="narrow panel center"><p class="eyebrow">A meeting of perspectives</p><h2>A partner is waiting.</h2><div class="match-portraits">${avatar(0,'You')}<span class="match-dots">···</span>${avatar(2,'Anonymous partner')}</div><span class="badge">Sample partner · same tag selected</span><p style="margin-top:20px">“${esc(find(blindTag)?.comment)}”</p><p class="small">You are the ${role}. Your simulated partner has accepted; you can accept to continue.</p>${btn('Accept Match','navigate','blind-summary','full')}${btn('Choose Another Tag','navigate','blind-tags','secondary full')}</div>`}
function blindSummary(){const a=find(blindTag);return `${back('blind-match')}<div class="narrow panel"><p class="eyebrow">Blind Eyes</p><h2>Match confirmed.</h2><p class="quote">${esc(a.comment)}</p><div class="status-line"><span>Your role</span><strong>${role}</strong></div><div class="status-line"><span>Difficulty</span><strong>${stars(a.stars)}</strong></div><div class="status-line"><span>Clues</span><strong>${a.stars}</strong></div><div class="status-line"><span>Total submissions</span><strong>${a.stars+1} (difficulty + 1)</strong></div><p class="small" style="margin-top:20px">Each wrong guess reveals the next clue. The final clue is followed by one last chance.</p>${btn('Start Chat','start-blind','','full')}</div>`}
function blindChat(){const g=S.game,a=art();return `${back()}<div class="layout"><div><p class="eyebrow">Blind Eyes · ${esc(g.role)}</p><h2>${g.finished?'Keep the conversation going.':'Find it through each other’s eyes.'}</h2><p class="small">Anonymous partner · local simulation · ${g.finished?'round complete':`${left()} attempts remaining`}</p>${g.role==='describer'||g.finished?fullImage(g.finished?a:{...a,title:'Artwork visible only to the describer'}):''}${g.role==='describer'&&!g.finished?'<p class="caption">You see the work. Its title and location stay hidden.</p>':''}<div style="margin-top:20px">${chatMessages(g.messages)}${composer()}</div></div><aside class="panel"><h3>${g.finished?'A shared discovery':'Your conversation'}</h3><p>Ask about colour, atmosphere and what stands out. Messages never use an attempt.</p><div class="stack">${!g.finished&&g.role==='guesser'?btn(left()===1?'Submit Final Answer':'Submit a Guess','navigate','guess'):''}${!g.finished&&g.role==='describer'?btn('Preview Guesser View','switch-role','','secondary'):''}${!g.finished&&g.role==='guesser'?btn('Preview Describer View','switch-role','','secondary'):''}${btn('Clue History','navigate','clues','secondary')}${btn('Open Map','navigate','map','secondary')}${g.finished?btn('Find a New Partner','navigate','blind-tags'):''}</div><p class="rule">The role switch is a demo control for testing both views on one device.</p></aside></div>`}
function locationPage(){return `${back(locationIntent==='teams'?'teams':'home')}<div class="narrow panel center"><img class="location-art" src="assets/ui/room-illustration.jpg" alt="Illustrated museum entrance"><p class="eyebrow">Gallery access</p><h2>Use your location.</h2><p>On-site teams and Live Gallery Chat require gallery verification. You can still browse and play alone without it.</p>${btn('Allow Location','request-location','','full')}${btn('Not Now · Limited Access','location-choice','denied','secondary full')}<div class="rule"><p>Classroom demonstration controls</p><div class="row" style="justify-content:center">${btn('Inside Gallery','location-choice','inside','secondary')}${btn('Outside Gallery','location-choice','outside','secondary')}</div><p style="margin:12px 0 0">GPS alone cannot verify an indoor classroom. These demo states let you test the access flow without claiming a real location check.</p></div></div>`}
function locationState(){const inside=S.location==='inside',outside=S.location==='outside';return `<div class="narrow panel center"><img class="location-art" src="assets/ui/${inside?'museum-hero':'study-illustration'}.jpg" alt="Illustrated gallery"><span class="badge ${inside?'':'warning'}">${inside?'Inside gallery · demo state':outside?'Outside gallery · demo state':'Location unavailable or not verified'}</span><h2 style="margin-top:23px">${inside?'You’re inside the gallery.':outside?'You’re outside the gallery.':'Location unavailable.'}</h2><p>${inside?'Your classroom demo access is active. Explore and meet other visitors.':outside?'On-site chat is read-only and team play is unavailable. You can still explore the museum.':'Permission may be off, the service unavailable, or the classroom boundary unconfigured. Continue with limited access or try the demo states.'}</p><div class="stack">${btn(inside?'Enter Gallery':'Continue Browsing','navigate',inside?locationIntent:'home')}${btn('Check Location Again','navigate','location','secondary')}${!inside?btn('How to Change Permission','location-help','','secondary'):''}</div></div>`}
async function requestLocation(){if(!navigator.geolocation){S.location='unavailable';go('location-state');return}toast('Use your browser’s location permission prompt.');navigator.geolocation.getCurrentPosition(()=>{S.location='unavailable';S.locationMode='boundary-not-configured';go('location-state');toast('Location was available, but no real classroom boundary is configured. No coordinates saved.');},()=>{S.location='denied';go('location-state');},{enableHighAccuracy:false,timeout:10000,maximumAge:0});}
const visitors=[{id:'willow',name:'Willow',bio:'Art always reminds me of places I’ve been. Happy to chat and maybe explore a challenge together.',area:1,looking:true},{id:'river',name:'River',bio:'Looking closely at light, colour and all the little things.',area:2,looking:false},{id:'juno',name:'Juno',bio:'I love hearing how a painting can mean different things to different people.',area:2,looking:true},{id:'maple',name:'Maple',bio:'Taking the slow route through the gallery today.',area:3,looking:false},{id:'kai',name:'Kai',bio:'The texture and quiet details always catch my eye.',area:4,looking:true},{id:'sage',name:'Sage',bio:'A good conversation makes every artwork a little bigger.',area:4,looking:true}];
function chat(){const permitted=S.location==='inside';return `${back()}${title('Live Gallery Chat','Meet another pair of eyes.','Share a memory, find a teammate, or begin with a hello.')}<div class="layout"><div><img class="location-art" style="height:245px" src="assets/ui/chat-illustration.jpg" alt="An illustrated gallery"><div class="panel ${permitted?'sage':'rose'}"><h3>${permitted?'Welcome to the gallery room.':'Gallery access is required.'}</h3><p>${permitted?'Choose a visitor or join the public conversation.':'Outside the gallery, conversations are read-only. Check in to post or invite visitors to an on-site team.'}</p><div class="row">${permitted?btn('Enter Public Conversation','open-chat','public'):btn('Verify Gallery Access','chat-location')}${btn('Recheck Access','chat-location','','secondary')}</div></div></div><div class="panel"><div class="section-head"><h3>Fellow visitors</h3><small>${visitors.filter(v=>!S.blocked.includes(v.id)).length} sample profiles</small></div><div class="chips"><button class="chip ${filter!=='Looking'?'active':''}" data-do="visitor-filter" data-value="All">All Visitors</button><button class="chip ${filter==='Looking'?'active':''}" data-do="visitor-filter" data-value="Looking">Looking for Team</button></div>${visitors.filter(v=>!S.blocked.includes(v.id)&&(filter!=='Looking'||v.looking)).map((v,i)=>`<button class="list-row" style="background:none;border-width:0 0 1px;width:100%;text-align:left" data-do="visitor" data-value="${v.id}">${avatar(i,v.name)}<span class="grow"><h4>${v.name} ${v.looking?'<span class="small" style="color:#9d5e3b">· Looking for team</span>':''}</h4><p>${esc(v.bio.slice(0,65))}…</p></span><span class="small">Area ${v.area} →</span></button>`).join('')}</div></div>`}
function visitor(){const v=visitors.find(v=>v.id===selectedVisitor)||visitors[0];return `${back('chat')}<div class="narrow panel center">${avatar(visitors.indexOf(v),v.name)}<p class="eyebrow" style="margin-top:20px">A fellow visitor · sample profile</p><h2>${v.name}</h2><span class="badge">${v.looking?'Looking for a Team':'Exploring the gallery'}</span><p class="small" style="margin-top:10px">Currently in Area ${v.area}</p><p>${esc(v.bio)}</p><div class="stack">${btn('Invite to Team','invite-visitor',v.id)}${btn('Message','open-chat',v.id,'secondary')}${btn(S.friends.includes(v.id)?'Added to Notebook':'Add to Notebook','friend',v.id,'secondary')}<div class="row" style="justify-content:center">${btn('Report','report',v.id,'secondary')}${btn('Block','block',v.id,'secondary')}</div></div></div>`}
function conversation(){const publicRoom=chatTarget==='public',v=visitors.find(v=>v.id===chatTarget),name=publicRoom?'Gallery Room':v?.name||'Your Team';const msgs=S.messages.filter(m=>m.room===chatTarget);const seeds=publicRoom?[{name:'Willow',text:'The landscape here reminds me of somewhere I grew up.',mine:false},{name:'Kai',text:'I notice the light first. Anyone looking for a team?',mine:false}]:[{name,text:'Hi! What caught your eye today?',mine:false}];return `${back('chat')}<div class="narrow"><p class="eyebrow">Live Gallery Chat · sample conversation</p><h2>${esc(name)}</h2>${S.location!=='inside'?'<div class="panel rose"><strong>You have left the gallery.</strong><p class="small">This conversation is read-only. Recheck your location to send messages.</p>'+btn('Recheck Access','chat-location','','secondary')+'</div>':''}${chatMessages([...seeds,...msgs])}${composer('gallery-message',S.location!=='inside')}<div class="row" style="margin-top:20px">${btn('Create a Team','navigate','chat-team','secondary')}${btn('Simulate Leaving Gallery','leave-gallery','','secondary')}</div></div>`}
function chatTeam(){if(S.location!=='inside'){locationIntent='chat-team';return locationPage()}return `${back('conversation')}<div class="narrow panel">${title('Looking together','Create a team invitation.','Choose a challenge and plan where to meet.')}<form data-form="chat-team"><label class="field"><span>Challenge</span><select name="art">${all().filter(a=>a.stars>=2).map(a=>`<option value="${a.id}">${esc(a.comment)} · ${a.stars}★</option>`).join('')}</select></label><label class="field"><span>Planned meeting area</span><select name="area">${areas.map((n,i)=>`<option value="${i+1}">Area ${i+1} — ${n}</option>`).join('')}</select></label><label class="field"><span>Invite sample visitors</span><select name="visitor"><option value="willow">Willow</option><option value="kai">Kai</option><option value="juno">Juno</option></select></label><button class="button full">Create Local Invite</button></form><p class="rule">This invitation stays on this device. No message is sent to a real person.</p></div>`}
function zoneMap(selected=null,mode='browse'){return `<div class="zone-map" aria-label="Four gallery areas">${areas.map((n,i)=>`<button type="button" class="zone ${Number(selected)===i+1?'selected':''}" ${mode==='hint'?'disabled':`data-do="${mode==='create'?'select-area':'map-area'}" data-value="${i+1}"`} aria-label="Area ${i+1}, ${n}${Number(selected)===i+1?', selected':''}"><b>${i+1}</b><span>${n}</span></button>`).join('')}</div>`}
function locationUnlocked(){const g=S.game;if(!g||g.finished)return false;const cs=suffixClues(art()),idx=cs.length-1;return g.mode==='blind'?g.cluesUnlocked>idx:Boolean(g.comments[idx])&&(idx===actor||g.shared.includes(idx))}
function map(){const game=active(),hint=game&&locationUnlocked();return `${back(game?gameRoute():'home',game?'Back to challenge':'Back')}<div class="page-title"><p class="eyebrow">The visitor’s companion</p><h1>${game?'Your discovery map.':'Gallery Map'}</h1><p>${game?'Search one part of the gallery at a time. The answer stays hidden.':'Twelve works. Four areas. Find a different way to wander.'}</p></div><div class="layout"><div class="map-wrap">${zoneMap(hint?art().area:null,game?'hint':'browse')}<p class="zone-meta">CLASSROOM EXHIBITION · FOUR SEARCH AREAS<br>Orientation guide, not the actual museum hanging locations.</p></div><aside><div class="panel ${hint?'sage':''}"><p class="eyebrow">${game?'Active challenge':'Floor guide'}</p><h3>${game?hint?`Area ${art().area} — ${areas[art().area-1]}`:'Location clue locked.':'Choose an area.'}</h3><p>${game?hint?'Q5 narrows your search to one quarter of the gallery. It does not reveal the exact hanging position, title or full image.':'Unlock your Q5 clue to see the search area. The complete artwork and title stay hidden until the result.':'Browse artworks by area, learn their stories and take a closer look.'}</p><div class="map-legend">${areas.map((n,i)=>`<div><b>${i+1}</b>${n}</div>`).join('')}</div>${game?btn('Back to Challenge','navigate',gameRoute(),'full'):''}</div><div class="panel"><h3>At a classroom label?</h3><form data-form="checkin">${field('Artwork label','code','text','BE-001 to BE-012','','required')}<button class="button secondary full">Check In · No Attempt Used</button></form>${S.lastCheckin?`<p class="small" style="margin-top:12px">Last check-in: ${esc(S.lastCheckin)}</p>`:''}</div></aside></div>`}
function area(){if(active())return map();return `${back('map')}<div class="page-title"><p class="eyebrow">Gallery catalogue</p><h1>Area ${mapArea}.</h1><p>${areas[mapArea-1]} · Discover the works in this part of the exhibition.</p></div><div class="art-grid">${works().filter(a=>a.area===mapArea).map(a=>`<button class="art-card" data-do="catalogue" data-value="${a.id}"><div class="frame"><img src="${esc(a.image)}" alt="${esc(a.title)}" data-art-image></div><p class="caption">${a.id}</p><h3>${esc(a.title)}</h3><p>${esc(a.artist)} · ${esc(a.date)}</p></button>`).join('')}</div>`}
function catalogue(){if(active())return map();const a=works().find(w=>w.id===selectedId);return `${back('area',`Back to Area ${a.area}`)}<div class="layout"><div>${fullImage(a)}</div><article><p class="eyebrow">${a.id} · Area ${a.area}</p><h1 style="font-size:45px">${esc(a.title)}</h1><p>${esc(a.titleZh||'')}</p><p class="small">${esc(a.artist)} · ${esc(a.date)}<br>${esc(a.medium)}</p><p>${esc(a.description)}</p>${a.source?`<a class="text-button" href="${esc(a.source)}" target="_blank" rel="noopener noreferrer">View museum catalogue ↗</a>`:''}<p class="rule">${esc(a.imageRights||'Image supplied by the task creator.')}<br>Classroom area is a prototype placement, not a museum location.</p>${btn('Back to Map','navigate','map','secondary')}</article></div>`}
const QUESTIONS=[['Q1 · Abstract','What feeling or memory does this detail evoke?','Think about emotion, atmosphere or personal memories.'],['Q2 · Story','What scene or story does it remind you of?','Think about a moment, place or story.'],['Q3 · Visual','What colours, shapes or textures stand out?','Describe visual elements without naming the work.'],['Q4 · Relation','How does this detail connect with its surroundings?','Think about how the part fits into the whole.'],['Q5 · Gallery area','Which area contains this artwork?','Choose one quarter, not an exact hanging position.']];
const draft=()=>S.draft||(S.draft={image:null,title:'',artist:'',artId:'',date:'',comment:'',crop:null,clues:['','','','',''],area:null});
const difficulty=r=>r<=0||r>1?0:r<.2?5:r<.4?4:r<.6?3:r<.8?2:1;
const draftStars=()=>{const d=draft();return difficulty((d.crop?.w||0)*(d.crop?.h||0))};
function wizard(content){return `${back('home')}<div class="narrow" style="max-width:720px"><p class="wizard-step">Leave Your Eyes · ${creatorStep} of 7</p><div class="progress-track"><span style="width:${creatorStep/7*100}%"></span></div>${content}</div>`}
function creator(){const d=draft(),n=draftStars();let content='';if(creatorStep===1)content=`${title('Create a task','Start with the whole picture.','Upload a full artwork, then select the detail that caught your eye.')}<label class="upload-zone">${icon('upload')}<strong>Upload Full Artwork</strong><p class="small">JPG, PNG or WebP · up to 10 MB</p><input type="file" id="artwork-file" accept="image/jpeg,image/png,image/webp" class="visually-hidden"></label>${d.image?`<div style="margin-top:20px">${fullImage({...d,title:'Your uploaded artwork'})}</div>`:''}<p class="small" style="margin-top:15px">Or choose a work from this exhibition to try the creation flow:</p><div class="chips">${window.ARTWORKS.map(a=>`<button class="chip" data-do="creator-sample" data-value="${a.id}">${esc(a.title)}</button>`).join('')}</div>${btn('Next','creator-next','','full')}`;
if(creatorStep===2)content=`${title('Artwork information','Give the work its identity.','Catalogue information stays hidden during an active challenge. An existing artwork keeps its answer ID; every new detail gets a separate challenge ID.')}<form data-form="creator-info">${field('Catalogue artwork title','title','text','Original artwork title',d.title,'required maxlength="120" '+(d.artworkId?'readonly':'' ))}${field('Artist / maker','artist','text','Artist name',d.artist,'required maxlength="100" '+(d.artworkId?'readonly':'' ))}${field('Unique answer ID','artId','text','e.g. LYE-001',d.artId,'required maxlength="30" '+(d.artworkId?'readonly':'' ))}${field('Date (optional)','date','text','e.g. 1889',d.date)}<p class="form-error" role="alert"></p><button class="button full">Next</button></form>`;
if(creatorStep===3){const c=d.crop;content=`${title('Select a detail','A small part, a bigger perspective.','Drag across the image to draw a crop. Draw again to change your selection.')}<div class="crop-stage" id="crop-stage" style="${d.imageBounds?`aspect-ratio:${d.imageWidth*d.imageBounds.w/(d.imageHeight*d.imageBounds.h)}`:''}"><img id="crop-image" src="${esc(d.image)}" alt="Full artwork for cropping" draggable="false" style="${d.imageBounds?`position:absolute;max-height:none;max-width:none;left:${-d.imageBounds.x/d.imageBounds.w*100}%;top:${-d.imageBounds.y/d.imageBounds.h*100}%;width:${100/d.imageBounds.w}%;height:${100/d.imageBounds.h}%`:''}">${c?`<div class="crop-box" style="left:${c.x*100}%;top:${c.y*100}%;width:${c.w*100}%;height:${c.h*100}%"></div>`:''}</div><p id="crop-ratio" class="crop-instruction">${c?`Crop area: ${(c.w*c.h*100).toFixed(1)}% · ${n} stars`:'Select a non-zero rectangle.'}</p><div class="row">${[.15,.3,.5,.7,.9].map((r,i)=>btn(`${5-i}★ crop`,'crop-preset',r,'secondary')).join('')}</div>${btn('Preview Difficulty','creator-next','','full')}`;}
if(creatorStep===4)content=`${title('Task settings','Your difficulty preview.','A smaller detail offers less visual information and a more difficult search.')}<div class="panel">${fragment({image:d.image,crop:d.crop,imageWidth:d.imageWidth,imageHeight:d.imageHeight,imageBounds:d.imageBounds})}<div class="status-line"><span>Crop area</span><strong>${(d.crop.w*d.crop.h*100).toFixed(1)}%</strong></div><div class="status-line"><span>Difficulty</span><strong>${stars(n)}</strong></div><div class="status-line"><span>Clues required</span><strong>${n} (Q${6-n}–Q5)</strong></div><div class="status-line"><span>Blind mode</span><strong>${n+1} submissions</strong></div><div class="status-line"><span>Borrow mode</span><strong>${n+1} − players</strong></div></div>${btn('Next','creator-next','','full')}`;
if(creatorStep===5)content=`${title('Personal comment','What stays with you?','This comment becomes the task title and a matching tag in Blind Eyes.')}<form data-form="creator-comment"><label class="field"><span>Your perspective</span><textarea name="comment" required maxlength="100" rows="4" placeholder="Reminds me of…">${esc(d.comment)}</textarea></label><p class="small">A personal reflection, separate from your numbered clues.</p><button class="button full">Next</button></form>`;
if(creatorStep===6){const q=5-n+creatorClue,question=QUESTIONS[q];content=`${title('Clue '+(creatorClue+1)+' of '+n,question[0],question[1])}${q===4?`${zoneMap(d.area,'create')}<p class="crop-instruction">${d.area?`Area ${d.area} selected — ${areas[d.area-1]}`:'Select an area to save Q5.'}</p>${btn('Save Area & Continue','creator-clue-next','','full')}`:`<form data-form="creator-clue"><label class="field"><span>Your clue</span><textarea name="clue" required maxlength="200" rows="4">${esc(d.clues[q])}</textarea></label><div class="panel sage small">${question[2]}</div><button class="button full">Confirm & Next</button></form>`}`;}
if(creatorStep===7)return creatorPreview();return wizard(content+`<div class="action-bar">${creatorStep>1?btn('Previous','creator-prev','','secondary'):''}${btn('Save Draft','save-draft','','secondary')}</div>`)}
function creatorPreview(){const d=draft(),n=draftStars();return wizard(`${title('Review your task','A new perspective, ready to share.','Check the artwork, detail and clues before publishing to this browser.')}<div class="preview-pair"><div>${fullImage({...d,title:'Full artwork'})}<p class="caption">Full artwork · ${esc(d.title)}</p></div><div>${fragment({image:d.image,crop:d.crop,imageWidth:d.imageWidth,imageHeight:d.imageHeight,imageBounds:d.imageBounds})}<p class="caption">Selected detail</p></div></div><div class="panel"><h3>${esc(d.comment)}</h3>${stars(n)}<p class="small">${esc(d.title)} · ${esc(d.artist)} · ${esc(d.artId)}</p><div class="status-line"><span>Crop area</span><strong>${(d.crop.w*d.crop.h*100).toFixed(1)}%</strong></div><div class="status-line"><span>Blind mode</span><strong>${n+1} submissions</strong></div><div class="status-line"><span>Borrow mode</span><strong>${n+1} − players</strong></div></div>${d.clues.slice(5-n).map((c,i)=>clueMarkup({q:6-n+i,text:c},true,false,d.area)).join('')}<p class="small">Publishing is local to this browser. It does not upload your image or task to a public gallery.</p><div class="stack">${btn('Publish to This Browser','publish')}${btn('Edit Task','creator-prev','','secondary')}</div>`)}
function creatorSuccess(){return `<div class="narrow panel center"><div class="result-seal">✓</div><p class="eyebrow">Leave Your Eyes</p><h2>Thank you for leaving your eyes.</h2><p>Your task is now available in this browser’s fragment collection.</p><div class="stack">${btn('View Task','select-art',selectedId)}${btn('Create Another','new-draft','','secondary')}${btn('Back to Home','navigate','home','secondary')}</div></div>`}
function profile(){return `${back()}<div class="profile-head">${avatar(0,S.user.name)}<div><p class="eyebrow">Your visitor’s notebook</p><h1>${esc(S.user.name)}</h1><span class="badge">Saved on this device</span></div></div><div class="stats"><div><strong>${S.history.reduce((n,h)=>n+h.reward,0)}</strong><small>Stars earned</small></div><div><strong>${S.history.filter(h=>h.success).length}</strong><small>Discoveries</small></div><div><strong>${S.published.length}</strong><small>Perspectives left</small></div></div><div class="layout"><section class="panel"><h3>Your discoveries</h3>${S.history.length?S.history.slice().reverse().map(h=>`<div class="list-row"><div class="grow"><h4>${esc(h.detailTitle||find(h.artId)?.title||h.artId)}</h4><p>${h.mode==='blind'?'Blind Eyes':'Borrow the Eyes'} · ${h.attempts} attempts · ${h.success?'Found':'Revealed'}</p></div><span class="stars">${h.reward?`+${h.reward} ★`:'—'}</span></div>`).join(''):'<div class="empty">Your first discovery is still ahead of you.</div>'}</section><aside class="panel"><h3>Your next chapter</h3><div class="stack">${active()?btn('Resume Your Challenge','navigate',gameRoute()):''}${btn('Explore Fragments','navigate','browse','secondary')}${btn(S.draft?'Resume Saved Draft':'Leave a Perspective','navigate','creator','secondary')}${btn('Location & Access','navigate','location','secondary')}${btn('Artwork Credits','navigate','sources','secondary')}</div></aside></div>`}
function sources(){if(active())return `${back(gameRoute())}<div class="narrow panel"><h2>Keep the mystery a little longer.</h2><p>Artwork titles and source records are available after this challenge ends. The collection uses credited public-domain images from The Metropolitan Museum of Art.</p>${btn('Return to Challenge','navigate',gameRoute())}</div>`;return `${back()}${title('The exhibition library','Twelve works, many perspectives.','Titles and dates are based on museum catalogue records. The personal reflections and challenge clues were written for this educational prototype. Each original artwork supports several independent detail challenges.')}<div class="panel">${window.ARTWORKS.map(a=>`<div class="list-row"><div class="grow"><h4>${esc(a.title)}</h4><p>${esc(a.titleZh)} · ${esc(a.artist)} · ${esc(a.date)}</p><p>${esc(a.imageRights)}</p></div><a class="text-button" href="${a.source}" target="_blank" rel="noopener noreferrer">Museum record ↗</a></div>`).join('')}</div><p class="small">The gallery is fictional and the four classroom areas are demonstration placements. Museum image files are included locally; no claim is made that the original works are present in the classroom.</p>`}
function mayReplaceGame(){return !active()||window.confirm('A challenge is in progress. Leave it and begin a new one? No reward will be added for the unfinished round.')}
function signIn(name='Visitor'){S.user={name:name.trim()||'Visitor'};persist();locationIntent='home';go('location')}
function setLocation(value){S.location=value;S.locationMode='classroom-demo';go('location-state')}
function saveCreatorInfo(form){const d=draft(),data=new FormData(form);for(const k of ['title','artist','artId','date'])d[k]=String(data.get(k)||'').trim();if(!d.artworkId&&works().some(a=>norm(a.id)===norm(d.artId))){form.querySelector('.form-error').textContent='This ID is already used. Choose a unique ID.';return false;}return true;}
function publishDraft(){const d=draft(),n=draftStars();if(!d.image||!d.title||!d.artist||!d.artId||!d.comment||!n||!d.area||d.clues.slice(5-n).some(c=>!c.trim())){toast('Complete the image, information, comment and all required clues.');return;}if(!d.artworkId&&works().some(a=>norm(a.id)===norm(d.artId))){toast('This artwork ID is already used. Edit the artwork information.');return;}const item={id:'D-LOCAL-'+Date.now().toString(36),artworkId:d.artworkId||d.artId,title:d.title,titleZh:'',artist:d.artist,date:d.date||'Date not provided',medium:'Image supplied by creator',category:'People',area:d.area,comment:d.comment,reflection:d.comment,description:'A perspective contributed in this browser. Artwork information is supplied by its creator and has not been independently verified.',clues:d.clues.slice(),ratio:d.crop.w*d.crop.h,crop:{...d.crop},imageWidth:d.imageWidth,imageHeight:d.imageHeight,imageBounds:d.imageBounds,stars:n,image:d.image,imageRights:'Creator-supplied image; rights not independently verified.'};S.published.push(item);if(!persist()){S.published.pop();return;}selectedId=item.id;S.draft=null;persist();go('creator-success')}
function bindCrop(){const stage=document.querySelector('#crop-stage');let start=null;const point=e=>{const r=stage.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}};stage.addEventListener('pointerdown',e=>{start=point(e);stage.setPointerCapture(e.pointerId);e.preventDefault()});stage.addEventListener('pointermove',e=>{if(!start)return;const p=point(e),d=draft();d.crop={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(start.x-p.x),h:Math.abs(start.y-p.y)};let box=stage.querySelector('.crop-box');if(!box){box=document.createElement('div');box.className='crop-box';stage.append(box);}Object.assign(box.style,{left:d.crop.x*100+'%',top:d.crop.y*100+'%',width:d.crop.w*100+'%',height:d.crop.h*100+'%'});document.querySelector('#crop-ratio').textContent=`Crop area: ${(d.crop.w*d.crop.h*100).toFixed(1)}% · ${draftStars()} stars`;});stage.addEventListener('pointerup',()=>{start=null;if(draft().crop?.w*draft().crop?.h<.0001){draft().crop=null;toast('Select a larger non-zero detail.');}persist()});stage.addEventListener('pointercancel',()=>start=null);}
function creatorNext(){const d=draft();if(creatorStep===1&&!d.image){toast('Upload or choose an artwork first.');return}if(creatorStep===3&&!draftStars()){toast('Select a non-zero detail first.');return}creatorStep=Math.min(7,creatorStep+1);d.step=creatorStep;persist();go('creator')}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-go]');if(nav){if(nav.dataset.go==='creator'&&S.draft)creatorStep=S.draft.step||1;go(nav.dataset.go);return;}const el=event.target.closest('[data-do]');if(!el)return;const action=el.dataset.do,v=el.dataset.value;
 if(action==='navigate'){if(v==='creator'&&S.draft)creatorStep=S.draft.step||1;go(v)}
 if(action==='guest')signIn();
 if(action==='about')notice('A front-end museum prototype','Accounts, matching, visitors and chat partners are demonstrations on this device. Game rules, crop creation, comments, clues and browser saves work locally. The twelve source artworks and interface images are included in this local version.');
 if(action==='terms')notice('Prototype terms & privacy','This is an educational local prototype. Use sample sign-in details. Passwords are never saved or transmitted. Uploaded images, messages and progress remain in this browser. No public account, identity service or messaging backend is connected.');
 if(action==='show-password'){const input=el.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';el.textContent=input.type==='password'?'Show':'Hide'}
 if(action==='logout'){S.user=null;S.location='unknown';persist();go('welcome')}
 if(action==='filter'){filter=v;detailPage=0;go('browse')}
 if(action==='difficulty-filter'){difficultyFilter=Number(v);detailPage=0;go('browse')}
 if(action==='detail-page'){detailPage=Number(v);go('browse')}
 if(action==='difficulty-help')notice('Smaller crop. Higher difficulty.','Crop percentage = (crop width × crop height) ÷ (full image width × full image height) × 100%. The image surface excludes any photographed frame. 1★: 80–100%; 2★: 60–<80%; 3★: 40–<60%; 4★: 20–<40%; 5★: >0–<20%. Zero area is invalid. High-star cards focus on tiny corners and ordinary surfaces; low-star cards deliberately show much more context.');
 if(action==='select-art'){selectedId=v;go('detail')}
 if(action==='begin-solo'){if(!mayReplaceGame())return;startGame('borrow',find(v),['You'])}
 if(action==='team-choice'){selectedId=v;teamTab='join';go('teams')}
 if(action==='team-tab'){teamTab=v;go('teams')}
 if(action==='join-team'){const a=find(selectedId);if(a.stars<2){toast('Choose a task with at least two stars to form a team.');return}teamSize=Math.min(a.stars,Number(v)+2);teamNames=['You','Maya','Leo','Willow','Kai'];S.teamName=['Art Explorers','Canvas Friends','Museum Wanderers'][Number(v)];go('lobby')}
 if(action==='begin-team'){if(S.location!=='inside'){locationIntent='lobby';go('location');return}if(!mayReplaceGame())return;startGame('borrow',find(v),teamNames.slice(0,teamSize))}
 if(action==='share-clue'){const i=Number(v),g=S.game;if(!g.comments[i]||g.shared.includes(i))return;g.shared.push(i);const c=suffixClues(art())[i];g.messages.push({name:g.players[i],text:`My clue (Q${c.q}): ${c.text}`,mine:i===0});persist();go('game-chat')}
 if(action==='choose-role'){role=v;go('blind-tags')}
 if(action==='blind-tag'){blindTag=v;go('blind-match')}
 if(action==='start-blind'){if(!mayReplaceGame())return;startGame('blind',find(blindTag),['You','Anonymous Partner'],role)}
 if(action==='switch-role'){S.game.role=S.game.role==='guesser'?'describer':'guesser';persist();go('blind-chat')}
 if(action==='request-location')requestLocation();
 if(action==='location-choice')setLocation(v);
 if(action==='location-help')notice('Location permissions','Use the site controls beside the address bar in your browser to change location permission. Browsers do not let this page open the system location settings directly. You can also use the explicit classroom demo states.');
 if(action==='chat-location'){locationIntent='chat';go('location')}
 if(action==='visitor-filter'){filter=v;go('chat')}
 if(action==='visitor'){selectedVisitor=v;go('visitor')}
 if(action==='open-chat'){chatTarget=v;go('conversation')}
 if(action==='invite-visitor'){if(S.location!=='inside'){locationIntent='chat-team';go('location')}else go('chat-team')}
 if(action==='friend'){if(!S.friends.includes(v))S.friends.push(v);persist();toast('Sample visitor added to your local notebook.');render()}
 if(action==='report')notice('Report preview','A real moderation service is not connected. No report has been sent. You can block this sample visitor locally.');
 if(action==='block'){if(!window.confirm('Hide this sample visitor in this browser?'))return;S.blocked.push(v);persist();go('chat')}
 if(action==='leave-gallery'){S.location='outside';go('conversation')}
 if(action==='map-area'){if(active())return;mapArea=Number(v);go('area')}
 if(action==='catalogue'){if(active())return;selectedId=v;go('catalogue')}
 if(action==='select-area'){const d=draft();d.area=Number(v);d.clues[4]=`Area ${v} — ${areas[Number(v)-1]}`;persist();go('creator')}
 if(action==='creator-sample'){const a=find(v),d=draft();Object.assign(d,{image:a.image,title:a.title,artist:a.artist,date:a.date,artId:a.id,artworkId:a.id,crop:null,imageWidth:a.imageWidth,imageHeight:a.imageHeight,imageBounds:a.imageBounds,source:a.source});persist();go('creator')}
 if(action==='creator-next')creatorNext();
 if(action==='creator-prev'){if(creatorStep===6&&creatorClue>0)creatorClue--;else creatorStep=Math.max(1,creatorStep-1);draft().step=creatorStep;go('creator')}
 if(action==='crop-preset'){const side=Math.sqrt(Number(v));draft().crop={x:(1-side)/2,y:(1-side)/2,w:side,h:side};persist();go('creator')}
 if(action==='save-draft'){draft().step=creatorStep;persist();toast('Draft saved in this browser.');}
 if(action==='creator-clue-next'){if(!draft().area){toast('Choose a gallery area first.');return}creatorStep=7;draft().step=7;persist();go('creator')}
 if(action==='publish')publishDraft();
 if(action==='new-draft'){S.draft=null;creatorStep=1;creatorClue=0;persist();go('creator')}
});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const data=new FormData(form),type=form.dataset.form;
 if(type==='auth'){const signup=form.dataset.signup==='true',password=String(data.get('password')||'');if(password.length<8){form.querySelector('.form-error').textContent='Use at least eight characters for this sample password.';return}if(signup&&password!==data.get('confirm')){form.querySelector('.form-error').textContent='The passwords do not match.';return}signIn(signup?String(data.get('name')):String(data.get('email')).split('@')[0]);form.reset();}
 if(type==='reset')go('reset-sent');
 if(type==='team-create'){teamSize=Number(data.get('size'));if(teamSize<2||teamSize>find(selectedId).stars)return;teamNames=['You','Maya','Leo','Willow','Kai'];S.teamName=String(data.get('name')).trim();go('lobby')}
 if(type==='comment'){const g=S.game;if(g.finished||g.comments[actor])return;g.comments[actor]=String(data.get('comment')).trim();if(!g.comments[actor])return;persist();go('clues')}
 if(type==='guess'){const g=S.game;if(g.mode!=='blind'&&g.players.some((_,i)=>!g.comments[i])){form.querySelector('.form-error').textContent='Each player must write one personal comment before a formal answer.';return}if(g.mode!=='blind'&&g.players.length>1&&S.location!=='inside'){form.querySelector('.form-error').textContent='Recheck gallery access before a team submission.';return}submitGuess(String(data.get('answer')).trim())}
 if(type==='game-message'){const g=S.game;if(g.mode!=='blind'&&g.players.length>1&&S.location!=='inside'){toast('Recheck gallery access before posting to the on-site team.');return;}const text=String(data.get('message')).trim();if(!text)return;g.messages.push({name:g.mode==='blind'?(g.role==='describer'?'You · Describer':'You · Guesser'):g.players[actor],text,mine:true});persist();render()}
 if(type==='gallery-message'){if(S.location!=='inside'){toast('Gallery access has expired. This conversation is read-only.');return}const text=String(data.get('message')).trim();if(!text)return;S.messages.push({room:chatTarget,name:S.user.name,text,mine:true});persist();render()}
 if(type==='chat-team'){selectedId=String(data.get('art'));const a=find(selectedId),who=visitors.find(v=>v.id===data.get('visitor'));teamSize=2;teamNames=['You',who?.name||'Willow'];S.teamName='Shared Perspectives';S.messages.push({room:chatTarget,name:S.user.name,text:`Local team invite: “${a.comment}”. Meet in Area ${data.get('area')}.`,mine:true});persist();go('lobby')}
 if(type==='checkin'){const input=norm(data.get('code')),a=works().find(a=>norm(a.id)===input);if(!a){toast('Use a label from BE-001 to BE-012, or an ID from a locally published work.');return}S.lastCheckin=a.id;persist();toast(`Checked in at ${a.id}. No attempt used.`);render()}
 if(type==='creator-info'){if(!saveCreatorInfo(form))return;creatorStep=3;draft().step=3;persist();go('creator')}
 if(type==='creator-comment'){draft().comment=String(data.get('comment')).trim();creatorStep=6;creatorClue=0;draft().step=6;persist();go('creator')}
 if(type==='creator-clue'){const q=5-draftStars()+creatorClue;draft().clues[q]=String(data.get('clue')).trim();creatorClue++;persist();go('creator')}
});
document.addEventListener('change',async event=>{if(event.target.id==='actor-select'){actor=Number(event.target.value);render()}if(event.target.id==='artwork-file'){const file=event.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a JPG, PNG or WebP image smaller than 10 MB.');return}try{const image=new Image(),uri=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=uri});const scale=Math.min(1,5000/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);draft().artworkId=null;draft().artId='';draft().title='';draft().artist='';draft().imageBounds=null;draft().image=canvas.toDataURL('image/jpeg',.94);draft().imageWidth=canvas.width;draft().imageHeight=canvas.height;draft().crop=null;persist();render()}catch{toast('This image could not be opened. Try another file.')}}});
document.addEventListener('error',event=>{if(event.target.matches?.('[data-art-image]')){const figure=event.target.closest('figure');const caption=figure?.querySelector('figcaption');if(caption)caption.hidden=false;}},true);
document.addEventListener('input',event=>{if(route!=='creator')return;const input=event.target,d=draft();if(creatorStep===2&&['title','artist','artId','date'].includes(input.name))d[input.name]=input.value;if(creatorStep===5&&input.name==='comment')d.comment=input.value;if(creatorStep===6&&input.name==='clue')d.clues[5-draftStars()+creatorClue]=input.value;});
if(S.user)route='home';
render();
